perl - <<'PL'
use strict;
use warnings;
my %count;
for my $file (qw(CLAUDE.md AGENTS.md)) {
    open(my $fh, '<', $file) or die "cannot read $file: $!";
    while (my $line = <$fh>) { $count{$file}++ if $line =~ /^\s*[-*] / }
    close $fh;
}
open(my $out, '>', 'report.txt') or die $!;
print $out "$_: $count{$_} bullet rules\n" for sort keys %count;
close $out;
